<?php
declare(strict_types=1);
require_once __DIR__.'/CommerceScheduleService.php';
/** Calendar and allocation review UI; all database writes stay in shared services. */
final class CommercePlanningExperience
{
    private static function e(mixed $v):string{return CommerceExperience::e($v);}
    private static function rows(PDO $db,string $sql,array $args=[]):array{$q=$db->prepare($sql);$q->execute($args);return$q->fetchAll();}
    public static function handles(string $action):bool{return in_array($action,['schedule_review','schedule_apply','allocation_review','allocation_apply','showtime_change','legacy_showtime','venue_timezone'],true);}
    private static function store(int $org,array $u,array $review):string
    {
        $key=bin2hex(random_bytes(16));$_SESSION['commerce_planning']??=[];if(count($_SESSION['commerce_planning'])>=20)array_shift($_SESSION['commerce_planning']);$_SESSION['commerce_planning'][$key]=$review+['org'=>$org,'actor'=>(int)$u['id'],'created'=>time()];return$key;
    }
    private static function review(int $org,array $u,string $key,string $type):array
    {
        $r=$_SESSION['commerce_planning'][$key]??null;if(!$r||$r['org']!==$org||$r['actor']!==(int)$u['id']||$r['type']!==$type||$r['created']<time()-1200)throw new RuntimeException('This review expired. Start a new preview.');return$r;
    }
    public static function command(PDO $db,array $u,int $org,string $action):string
    {
        CommerceAccess::demand($db,$u,$org,$action==='venue_timezone'?'venues':'inventory');$id=(int)($_POST['id']??0);
        if($action==='schedule_review'){$production=(int)($_POST['production']??0);$layout=(int)($_POST['layout']??0);$prices=json_decode((string)($_POST['prices']??''),true,512,JSON_THROW_ON_ERROR);if(!is_array($prices))throw new RuntimeException('Enter a valid pricing document.');$input=array_intersect_key($_POST,array_flip(['dates','times','offsets','weekly_enabled','range_start','range_end','weekly','exceptions','dst_choice','seating_mode']));$preview=CommerceScheduleService::preview($db,$u,$org,$production,$layout,$prices,$input);$key=self::store($org,$u,compact('production','layout','prices','input','preview')+['type'=>'schedule']);return CommerceExperience::url('schedule',['review'=>$key]);}
        if($action==='schedule_apply'){$r=self::review($org,$u,(string)($_POST['review_key']??''),'schedule');$ids=CommerceScheduleService::create($db,$u,$org,$r['production'],$r['layout'],$r['prices'],$r['input'],$r['preview']['hash'],(string)$_POST['review_key']);$_SESSION['commerce_notice']='Created '.count($ids).' actual performances with closed sales. No other dates received inventory.';return CommerceExperience::url('performances');}
        if($action==='allocation_review'){$scope=['production'=>(int)($_POST['production']??0),'mode'=>(string)($_POST['scope']??'selected'),'ids'=>(array)($_POST['performances']??[]),'from'=>(string)($_POST['from']??''),'to'=>(string)($_POST['to']??'')];$ids=CommerceInventoryService::allocationScope($db,$u,$org,$scope);$seats=(array)($_POST['seats']??[]);$state=(string)($_POST['state']??'');$reason=(string)($_POST['reason']??'');$preview=CommerceInventoryService::allocationPreview($db,$u,$org,$ids,$seats,$state,$reason);$key=self::store($org,$u,compact('scope','ids','seats','state','reason','preview')+['type'=>'allocation']);return CommerceExperience::url('blocks',['review'=>$key]);}
        if($action==='allocation_apply'){$r=self::review($org,$u,(string)($_POST['review_key']??''),'allocation');$result=CommerceInventoryService::allocateMany($db,$u,$org,$r['ids'],$r['seats'],$r['state'],$r['reason'],$r['preview']['hash'],(string)$_POST['review_key'],$r['scope']);$_SESSION['commerce_notice']='Applied '.self::e($result['state']).' to '.$result['affected'].' positions across '.count($result['performances']).' performances. Audit history retained.';return CommerceExperience::url('blocks',['production'=>$r['scope']['production']]);}
        if($action==='venue_timezone'){CommerceScheduleService::venueTimezone($db,$u,$org,$id,(string)($_POST['timezone']??''));return CommerceExperience::url('venues');}
        if($action==='legacy_showtime'){CommerceScheduleService::reviewLegacy($db,$u,$org,$id,(string)($_POST['timezone']??''),(string)($_POST['offset']??''),(string)($_POST['reason']??''));return CommerceExperience::url('performance',['id'=>$id]);}
        CommerceScheduleService::change($db,$u,$org,$id,(string)($_POST['starts']??''),(string)($_POST['offset']??''),(string)($_POST['status']??''),(string)($_POST['reason']??''),(string)($_POST['version']??''),!empty($_POST['acknowledge_paid']));return CommerceExperience::url('performance',['id'=>$id]);
    }
    private static function productionSelect(PDO $db,int $selected):void
    {
        echo '<label>Production<select name="production" required><option value="">Choose a production</option>';foreach(self::rows($db,"SELECT id,title FROM productions WHERE lifecycle_stage IN ('upcoming','planning','in_production','performing') ORDER BY title") as $p)echo '<option value="'.(int)$p['id'].'" '.($selected===(int)$p['id']?'selected':'').'>'.self::e($p['title']).'</option>';echo '</select></label>';
    }
    public static function schedule(PDO $db,array $u,int $org):void
    {
        CommerceAccess::demand($db,$u,$org,'inventory');if(isset($_GET['review'])){self::scheduleReview($db,$u,$org,(string)$_GET['review']);return;}$production=(int)($_GET['production']??0);$month=(string)($_GET['month']??date('Y-m'));if(!preg_match('/^\d{4}-(?:0[1-9]|1[0-2])$/',$month))$month=date('Y-m');echo '<h2>Performance schedule</h2><p>Select exact showtimes or build a weekly template, then review every date before creating inventory. Selecting a calendar day alone does not create a performance.</p><form method="get"><input type="hidden" name="tab" value="schedule">';self::productionSelect($db,$production);CommerceExperience::input('month','Calendar month','month',$month,'required');echo '<button>View calendar</button></form>';if(!$production)return;
        $performances=self::rows($db,'SELECT * FROM commerce_performances WHERE organization_id=? AND production_id=? ORDER BY starts_at',[$org,$production]);$byDate=[];foreach($performances as $p)$byDate[substr($p['starts_at'],0,10)][]=$p;$first=new DateTimeImmutable($month.'-01');echo '<div class="commerce-calendar" aria-label="'.self::e($first->format('F Y')).' performance calendar">';foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day)echo '<strong aria-hidden="true">'.$day.'</strong>';for($i=1;$i<(int)$first->format('N');$i++)echo '<span></span>';for($day=1;$day<=(int)$first->format('t');$day++){$date=$month.'-'.sprintf('%02d',$day);echo '<div class="commerce-calendar-day"><button type="button" data-calendar-date="'.$date.'" aria-label="Select '.$date.'">'.$day.'</button>';foreach($byDate[$date]??[] as $p)echo '<a href="'.self::e(CommerceExperience::url('performance',['id'=>$p['id']])).'">'.self::e(substr($p['starts_at'],11,5).' · '.$p['schedule_status']).'</a>';echo '</div>';}echo '</div>';
        CommerceExperience::form('schedule_review',['production'=>$production]);echo '<label>Published venue / layout<select name="layout" required><option value="">Choose layout</option>';foreach(self::rows($db,"SELECT l.id,l.version_number,s.name auditorium,v.name venue,v.timezone_name FROM commerce_layouts l JOIN commerce_spaces s ON s.id=l.space_id AND s.organization_id=l.organization_id JOIN commerce_venues v ON v.id=s.venue_id AND v.organization_id=s.organization_id WHERE l.organization_id=? AND l.status='published'",[$org]) as $l)echo '<option value="'.(int)$l['id'].'">'.self::e($l['venue'].' / '.$l['auditorium'].' · v'.$l['version_number'].' · '.($l['timezone_name']?:getenv('COMMERCE_VENUE_TIMEZONE')?:getenv('APP_TIMEZONE')?:'America/New_York')).'</option>';echo '</select></label><label>Seating mode<select name="seating_mode"><option value="reserved">Reserved seats</option><option value="general_admission">General admission (layout defines capacity)</option></select></label><h3>Individually selected showtimes</h3><p>Choose a day above or use each row’s date picker. Add separate rows for matinee and evening shows.</p><div data-showtime-rows>';self::showtimeRow();echo '</div><button type="button" data-add-showtime>Add another exact showtime</button><fieldset><legend>Weekly template (optional)</legend><label><input type="checkbox" name="weekly_enabled" value="1"> Also generate these weekly showtimes</label><div class="commerce-columns">';CommerceExperience::input('range_start','Template start date','date');CommerceExperience::input('range_end','Template end date','date');echo '</div><p>Use 24-hour times separated by commas, for example 14:00, 19:00. Leave days without performances blank.</p><div class="commerce-columns">';foreach([1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'] as $n=>$day)CommerceExperience::input('weekly['.$n.']',$day.' times','text','','placeholder="HH:MM, HH:MM"');echo '</div></fieldset><label>Exceptions<textarea name="exceptions" rows="3" placeholder="YYYY-MM-DD or YYYY-MM-DDTHH:MM"></textarea></label><p>Separate exclusions with commas or new lines. A date removes every show that day; a date and time removes only that show.</p><label>Repeated daylight-saving hour<select name="dst_choice"><option value="">Require explicit resolution if a time occurs twice</option><option value="earlier">Use the first occurrence of a repeated hour</option><option value="later">Use the second occurrence of a repeated hour</option></select></label><p>Nonexistent spring-forward times are always rejected. Review lists each local time, UTC offset and UTC instant.</p>';
        $prices=$performances?json_encode(json_decode($performances[count($performances)-1]['prices_json'],true),JSON_PRETTY_PRINT):'';echo '<label>Ticket prices by zone and category (integer cents)<textarea name="prices" rows="5" required>'.self::e($prices).'</textarea></label><p>New performances start with closed sales, no fee, no tax and no discount. Configure those settings before opening sales. The layout and ticket prices shown in review are copied to each new performance.</p><button>Review exact performances</button></form>';
    }
    private static function showtimeRow():void
    {
        echo '<div class="commerce-showtime-row"><label>Exact date<input type="date" name="dates[]" data-exact-date></label><label>Local time<input type="time" name="times[]" step="60"></label><label>UTC offset if needed<input name="offsets[]" placeholder="For example -04:00" maxlength="6"></label><button type="button" data-remove-showtime>Remove showtime</button></div>';
    }
    private static function scheduleReview(PDO $db,array $u,int $org,string $key):void
    {
        $r=self::review($org,$u,$key,'schedule');$preview=CommerceScheduleService::preview($db,$u,$org,$r['production'],$r['layout'],$r['prices'],$r['input']);$context=self::rows($db,'SELECT p.title,v.name venue,s.name auditorium,l.version_number FROM productions p JOIN commerce_layouts l ON l.id=? AND l.organization_id=? JOIN commerce_spaces s ON s.id=l.space_id AND s.organization_id=l.organization_id JOIN commerce_venues v ON v.id=s.venue_id AND v.organization_id=s.organization_id WHERE p.id=?',[$r['layout'],$org,$r['production']])[0];echo '<h2>Review exact performances</h2><p>'.self::e($context['title'].' · '.$context['venue'].' / '.$context['auditorium'].' · layout v'.$context['version_number']).'</p><p>'.count($preview['times']).' performances · '.self::e(str_replace('_',' ',$preview['seating_mode'])).' · timezone '.self::e($preview['timezone']).'. Only these showtimes receive ticket inventory.</p>';foreach($preview['conflicts'] as $conflict)echo '<p role="alert">'.self::e($conflict).'</p>';echo '<div class="commerce-table-scroll"><table><caption>Actual showtimes to create</caption><thead><tr><th>Local date and time</th><th>UTC offset</th><th>UTC instant</th></tr></thead><tbody>';foreach($preview['times'] as $time)echo '<tr><td>'.self::e($time['local']).'</td><td>'.self::e($time['offset']).'</td><td>'.self::e($time['utc']).'</td></tr>';echo '</tbody></table></div><details><summary>Reviewed ticket prices and layout</summary><p>Layout #'.(int)$r['layout'].'</p><pre>'.self::e(json_encode($r['prices'],JSON_PRETTY_PRINT)).'</pre></details>';if(!$preview['conflicts']&&hash_equals($preview['hash'],$r['preview']['hash'])){CommerceExperience::form('schedule_apply',['review_key'=>$key]);echo '<button>Create these '.count($preview['times']).' performances with closed sales</button></form>';}else echo '<p>Resolve conflicts or configuration changes and create a fresh review. Nothing has been created.</p>';echo '<a href="'.self::e(CommerceExperience::url('schedule',['production'=>$r['production']])).'">Back to schedule editor</a>';
    }
    public static function blocks(PDO $db,array $u,int $org):void
    {
        CommerceAccess::demand($db,$u,$org,'inventory');if(isset($_GET['review'])){self::allocationReview($db,$u,$org,(string)$_GET['review']);return;}$production=(int)($_GET['production']??0);echo '<h2>Block or release seats across shows</h2><p>Preview the full scope before applying. Any sold, held, missing or incompatible seat prevents the entire operation.</p><form method="get"><input type="hidden" name="tab" value="blocks">';self::productionSelect($db,$production);echo '<button>Choose production</button></form>';if(!$production)return;$performances=self::rows($db,'SELECT * FROM commerce_performances WHERE organization_id=? AND production_id=? ORDER BY starts_at',[$org,$production]);if(!$performances){echo '<p>No actual performances exist for this production.</p>';return;}
        CommerceExperience::form('allocation_review',['production'=>$production]);echo '<label>Performance scope<select name="scope"><option value="selected">Selected performances (one or more)</option><option value="range">Scheduled performances in a date range</option><option value="all">All performances in this production</option></select></label><fieldset><legend>Selected performances</legend>';foreach($performances as $p)echo '<label><input type="checkbox" name="performances[]" value="'.(int)$p['id'].'" '.((int)($_GET['id']??0)===(int)$p['id']?'checked':'').'>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['schedule_status'].' · #'.$p['id']).'</label>';echo '</fieldset><div class="commerce-columns">';CommerceExperience::input('from','Range start (venue-local date)','date');CommerceExperience::input('to','Range end (venue-local date)','date');echo '</div><label>Action<select name="state"><option value="blocked">Block seats</option><option value="house">Create house holds</option><option value="complimentary">Allocate for complimentary issuance</option><option value="released">Release eligible blocks / house / complimentary allocations</option></select></label>';
        $seats=[];foreach($performances as $p)foreach(CommerceInventoryService::inventory($db,$org,(int)$p['id']) as $item){$s=json_decode($item['seat_json'],true);$seats[$item['seat_key']]=$s['section_name'].' / '.$s['row_name'].' / '.$s['label'];}uasort($seats,'strnatcasecmp');echo '<fieldset><legend>Seats (validated in every affected performance)</legend><p>If layouts differ, a missing key is a conflict. Narrow the scope or create separate reviewed operations.</p><div class="commerce-seat-list">';foreach($seats as $key=>$label)echo '<label><input type="checkbox" name="seats[]" value="'.self::e($key).'">'.self::e($label.' · '.$key).'</label>';echo '</div></fieldset>';CommerceExperience::input('reason','Blocking or release reason','text','','required maxlength="500"');echo '<button>Preview affected performances & seats</button></form>';
    }
    private static function allocationReview(PDO $db,array $u,int $org,string $key):void
    {
        $r=self::review($org,$u,$key,'allocation');$preview=CommerceInventoryService::allocationPreview($db,$u,$org,$r['ids'],$r['seats'],$r['state'],$r['reason']);$currentScope=CommerceInventoryService::allocationScope($db,$u,$org,$r['scope']);$stale=$currentScope!==$r['ids']||!hash_equals($preview['hash'],$r['preview']['hash']);echo '<h2>Review seat allocation</h2><p>'.count($r['ids']).' performances × '.count($r['seats']).' positions · action '.self::e($r['state']).'</p><p>Reason: '.self::e($r['reason']).'</p>';if($stale)echo '<p role="alert">The scope or inventory changed. Start a fresh preview; nothing has been applied.</p>';echo '<p>Seat keys: '.self::e(implode(', ',$r['seats'])).'</p><div class="commerce-table-scroll"><table><caption>Affected showtimes and seat states</caption><thead><tr><th>Performance / local time</th><th>Seat</th><th>Current state</th><th>Validation</th></tr></thead><tbody>';foreach($preview['rows'] as $row)echo '<tr><td>#'.(int)$row['performance'].' · '.self::e($row['showtime'].' '.$row['timezone'].' · '.$row['venue']).'</td><td>'.self::e($row['seat'].' · '.$row['description']).'</td><td>'.self::e($row['before']).'</td><td>'.self::e($row['conflict']??'Eligible').'</td></tr>';echo '</tbody></table></div>';if(!$stale&&!$preview['conflicts']){CommerceExperience::form('allocation_apply',['review_key'=>$key]);echo '<button>Apply to all '.count($preview['rows']).' positions</button></form>';}else echo '<p role="alert">No partial application is allowed. Change the seats or performance scope and review again.</p>';echo '<a href="'.self::e(CommerceExperience::url('blocks',['production'=>$r['scope']['production']])).'">Revise scope or seats</a>';
    }
    public static function showtimeControls(PDO $db,array $u,int $org,array $p):void
    {
        echo '<details><summary>Performance schedule & cancellation</summary><p>'.self::e(CommercePerformancePolicy::label($p).' · '.$p['schedule_status']).'</p>';
        if(!$p['starts_at_utc']){CommerceExperience::form('legacy_showtime',['id'=>$p['id']]);echo '<p>This historical local time has not been converted. Review its actual venue timezone and offset; existing wall times, tickets and money will be retained.</p>';CommerceExperience::input('timezone','Historical venue timezone (IANA)','text',CommercePerformancePolicy::venueTimezone($db,$org,(int)$p['layout_id']),'required');CommerceExperience::input('offset','UTC offset for ambiguous hour (optional)','text','','placeholder="-04:00"');CommerceExperience::input('reason','Timezone review evidence / reason','text','','required maxlength="500"');echo '<button>Confirm historical timezone without changing local time</button></form>';}
        elseif($p['starts_at_utc']>gmdate('Y-m-d H:i:s')&&!in_array($p['schedule_status'],['cancelled','completed'],true)){CommerceExperience::form('showtime_change',['id'=>$p['id'],'version'=>CommerceScheduleService::version($p)]);CommerceExperience::input('starts','Exact local showtime','datetime-local',str_replace(' ','T',substr($p['starts_at'],0,16)),'required');CommerceExperience::input('offset','UTC offset (explicit for repeated hour)','text','','maxlength="6" placeholder="-04:00 if needed"');echo '<label>Schedule status<select name="status">';foreach(['scheduled'=>'Scheduled / published performance','draft'=>'Draft / unpublished performance','cancelled'=>'Cancel this performance'] as $key=>$label)echo '<option value="'.$key.'" '.($p['schedule_status']===$key?'selected':'').'>'.$label.'</option>';echo '</select></label><p>Dates cannot change after any order history. Cancellation retains paid orders/tickets, closes sales and door entry, and voids unpaid holds. Pending/uncertain payments must first be reconciled. No refund or email is automatic.</p>';CommerceExperience::input('reason','Schedule change reason','text','','required maxlength="500"');echo '<label><input type="checkbox" name="acknowledge_paid" value="1"> I acknowledge existing paid ticket holders and will handle customer contact / refunds separately if cancelling or unpublishing.</label><button>Save schedule change / cancellation</button></form>';}
        else echo '<p>Past, completed and cancelled showtimes are retained as history. No schedule changes are permitted here.</p>';echo '</details>';
    }
    private static function offset(int $minutes):string{return($minutes<0?'-':'+').sprintf('%02d:%02d',intdiv(abs($minutes),60),abs($minutes)%60);}
}
